    def dist(a, b):
        if a == b:
            return 0
        if dist_matrix is not None:
            try:
                return dist_matrix[a][b]
            except Exception:
                try:
                    return dist_matrix[b][a]
                except Exception:
                    pass
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is not None and cb is not None:
            dx = ca[0] - cb[0]
            dy = ca[1] - cb[1]
            return (dx * dx + dy * dy) ** 0.5
        try:
            return abs(a - b)
        except Exception:
            return 1

    customer_ids = []
    if customers is not None:
        try:
            n = len(customers)
            i = 0
            while i < n:
                cid = i
                try:
                    v = customers[i]
                    try:
                        cid = v["id"]
                    except Exception:
                        pass
                except Exception:
                    pass
                if cid != depot:
                    customer_ids.append(cid)
                i += 1
        except Exception:
            try:
                for cid in customers:
                    if cid != depot:
                        customer_ids.append(cid)
            except Exception:
                pass
    if not customer_ids:
        try:
            for cid in demands:
                if cid != depot:
                    customer_ids.append(cid)
        except Exception:
            pass
    if not customer_ids:
        try:
            for cid in coords:
                if cid != depot:
                    customer_ids.append(cid)
        except Exception:
            pass

    seen = {}
    uniq = []
    for cid in customer_ids:
        if cid not in seen:
            seen[cid] = 1
            uniq.append(cid)
    customer_ids = uniq

    if capacity is None:
        total = 0
        for cid in customer_ids:
            total += demand_of(cid)
        capacity = total if total > 0 else 1
    try:
        capacity = int(capacity)
    except Exception:
        capacity = 1

    depot_coord = coord_of(depot)
    have_coords = depot_coord is not None

    items = []
    if have_coords:
        dx0 = depot_coord[0]
        dy0 = depot_coord[1]
        for cid in customer_ids:
            c = coord_of(cid)
            if c is not None:
                dx = c[0] - dx0
                dy = c[1] - dy0
                ang = 0
                if dx != 0 or dy != 0:
                    if dx >= 0 and dy >= 0:
                        ang = dy / (dx + dy + 1e-12)
                    elif dx < 0 <= dy:
                        ang = 1 + (-dx) / ((-dx) + dy + 1e-12)
                    elif dx < 0 and dy < 0:
                        ang = 2 + (-dy) / ((-dx) + (-dy) + 1e-12)
                    else:
                        ang = 3 + dx / (dx + (-dy) + 1e-12)
                items.append((ang, dx * dx + dy * dy, cid))
            else:
                items.append((10**18, 10**18, cid))
    else:
        for cid in customer_ids:
            items.append((demand_of(cid), cid, cid))

    i = 1
    while i < len(items):
        x = items[i]
        j = i - 1
        while j >= 0 and items[j] > x:
            items[j + 1] = items[j]
            j -= 1
        items[j + 1] = x
        i += 1

    ordered = []
    for t in items:
        ordered.append(t[2])

    routes = []
    route = []
    load = 0
    for cid in ordered:
        d = demand_of(cid)
        if route and load + d > capacity:
            routes.append(route)
            route = []
            load = 0
        if d > capacity and route:
            routes.append(route)
            route = []
            load = 0
        route.append(cid)
        load += d
        if load >= capacity:
            routes.append(route)
            route = []
            load = 0
    if route:
        routes.append(route)

    # Repair: ensure every customer appears exactly once.
    count = {}
    for r in routes:
        for cid in r:
            count[cid] = count.get(cid, 0) + 1

    missing = []
    for cid in customer_ids:
        if count.get(cid, 0) == 0:
            missing.append(cid)

    if missing:
        for cid in missing:
            best_r = -1
            best_pos = 0
            best_cost = None
            d = demand_of(cid)
            for ri in range(len(routes)):
                r = routes[ri]
                load = 0
                for x in r:
                    load += demand_of(x)
                if load + d > capacity:
                    continue
                prev = depot
                for pos in range(len(r) + 1):
                    nxt = depot if pos == len(r) else r[pos]
                    cost = dist(prev, cid) + dist(cid, nxt) - dist(prev, nxt)
                    if best_cost is None or cost < best_cost:
                        best_cost = cost
                        best_r = ri
                        best_pos = pos
                    if pos < len(r):
                        prev = r[pos]
            if best_r == -1:
                routes.append([cid])
            else:
                routes[best_r].insert(best_pos, cid)

    # Remove duplicates if any, keeping first occurrence.
    seen = {}
    cleaned = []
    for r in routes:
        nr = []
        for cid in r:
            if seen.get(cid, 0) == 0:
                seen[cid] = 1
                nr.append(cid)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    # Local improvement: intra-route adjacent swaps if they reduce length.
    for r in routes:
        improved = True
        while improved:
            improved = False
            n = len(r)
            k = 0
            while k + 1 < n:
                a = depot if k == 0 else r[k - 1]
                b = r[k]
                c = r[k + 1]
                d = depot if k + 2 >= n else r[k + 2]
                old = dist(a, b) + dist(b, c) + dist(c, d)
                new = dist(a, c) + dist(c, b) + dist(b, d)
                if new + 1e-12 < old:
                    r[k], r[k + 1] = r[k + 1], r[k]
                    improved = True
                k += 1

    # Final sanity: append any accidental omissions as singleton routes.
    final_seen = {}
    for r in routes:
        for cid in r:
            final_seen[cid] = 1
    for cid in customer_ids:
        if final_seen.get(cid, 0) == 0:
            routes.append([cid])

    return routes
